  clusterDeployState: 'REMOVE_HAWQ_STANDBY',

  hawqRemoveStandbyCustomCommand: "REMOVE_HAWQ_STANDBY",

  hawqServiceName: "HAWQ",

  hawqMasterComponentName: "HAWQMASTER",

