      onPrimary: function onPrimary() {
        this._super();
        primary();
      },
      onSecondary: function onSecondary() {
        this._super();
        this.get('controller').clearConfigsChanges();
      },
      onClose: function onClose() {
        this._super();
        this.get('controller').clearConfigsChanges();
      }
