var App = require('app');

App.WizardStep5Controller = Em.Controller.extend(App.BlueprintMixin, App.AssignMasterComponents, {

  name: "wizardStep5Controller",

  _goNextStepIfValid: function _goNextStepIfValid() {
    App.set('router.nextBtnClickInProgress', false);
    if (!this.get('submitDisabled')) {
      App.router.send('next');
    }
  },

  _additionalClearSteps: function _additionalClearSteps() {
    var parentController = App.router.get(this.get('content.controllerName'));
    if (parentController && parentController.get('content.componentsFromConfigs')) {
      parentController.clearConfigActionComponents();
    }
  }

});

