      serviceConfigCategories.pushObjects([App.ServiceConfigCategory.create({ name: 'KDC', displayName: 'KDC' }), App.ServiceConfigCategory.create({ name: 'Kadmin', displayName: 'Kadmin' }), App.ServiceConfigCategory.create({ name: 'General', displayName: 'General' })]);
