  categories: [categoryObject.create({ value: 'all', labelPath: 'hostPopup.status.category.all' }), categoryObject.create({ value: 'pending', labelPath: 'hostPopup.status.category.pending' }), categoryObject.create({ value: 'in_progress', labelPath: 'hostPopup.status.category.inProgress' }), categoryObject.create({ value: 'failed', labelPath: 'hostPopup.status.category.failed' }), categoryObject.create({ value: 'completed', labelPath: 'hostPopup.status.category.success' }), categoryObject.create({ value: 'aborted', labelPath: 'hostPopup.status.category.aborted' }), categoryObject.create({ value: 'timedout', labelPath: 'hostPopup.status.category.timedout' })],

